import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount, uint256 nDeposits) public {
        vm.assume(amount > 0);
        nDeposits = bound(nDeposits, 1, 50);
        address actor = address(0xA11CE);
