pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address actor, uint256 amount) public {
        vm.assume(actor != address(0));
        amount = bound(amount, 1, type(uint128).max);

        // fund the contract through its payable receive() via a low-level call
        vm.deal(address(this), amount);
        (bool sent, ) = address(c).call{value: amount}("");
        assertTrue(sent, "funding via receive should succeed");

        // an arbitrary (possibly non-owner) actor tries to drain the contract
        vm.prank(actor);
        bool ok;
        try c.withdrawAll() { ok = true; } catch { ok = false; }

        // General rule: withdrawAll may only succeed for the owner.
        assertTrue(ok == (actor == c.owner()), "withdrawAll must revert for non-owners");
    }

    receive() external payable {}
}

