// Helper to hold deposited funds and probe withdrawAll as an arbitrary code-bearing counterparty
contract Depositor {
    C public target;
    constructor(C _c) payable { target = _c; }

    function fund(uint96 amount) external payable {
        (bool ok, ) = address(target).call{value: amount}("");
        require(ok, "deposit failed");
    }

    function tryWithdrawAll() external returns (bool ok, uint256 balAfter) {
        try target.withdrawAll() {
            ok = true;
        } catch {
            ok = false;
        }
        balAfter = address(target).balance;
    }

    receive() external payable {}
}
}

