pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 value, uint256 balance) public {
        // admissible domain: contract holds a positive balance; value unconstrained
        vm.assume(balance > 0);
        vm.deal(address(c), balance);

        // the test contract is the owner (deployed it in setUp), so withdraw is callable
        bool ok;
        try c.withdraw(value) { ok = true; } catch { ok = false; }

        // GENERAL RULE: a withdrawal may only succeed if the requested amount
        // does not exceed the contract's balance; requesting more than the
        // balance must revert. P satisfies this (transfer(value) fails);
        // M breaks it because it always transfers the full balance and thus
        // succeeds even when value > balance.
        assertTrue(!(ok && value > balance));
    }
}

